.github/workflows/build.yml
---
name: Build OmniBrowser & VPN Tunnel Pro APK

on:
  push:
    branches: [ "main", "master", "v4.*" ]
    tags: [ "v*" ]
  workflow_dispatch:

permissions:
  contents: write

jobs:
  build:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout Source
        uses: actions/checkout@v4

      - name: Set up JDK 17
        uses: actions/setup-java@v4
        with:
          java-version: '17'
          distribution: 'temurin'

      - name: Setup Gradle
        uses: gradle/actions/setup-gradle@v4

      - name: Run Unit Tests & Assemble Signed Release APK (R8 + Unified Keystore)
        run: |
          chmod +x gradlew
          ./gradlew testDebugUnitTest assembleRelease --stacktrace

      - name: Prepare Signed APK Artifact
        run: |
          mkdir -p dist
          VER=$(grep -h -m1 -oE 'versionName *=? *"[^"]+"' app/build.gradle* | head -1 | sed -E 's/.*"([^"]+)".*/\1/')
          if [[ "$GITHUB_REF" == refs/tags/* ]]; then BASE="OmniBrowser-VPN-Tunnel-Pro-${GITHUB_REF_NAME}-arm64-release"; else BASE="OmniBrowser-VPN-Tunnel-Pro-v${VER}-arm64-release"; fi
          cp app/build/outputs/apk/release/app-release.apk "dist/${BASE}.apk"
          echo "APK_BASE=${BASE}" >> "$GITHUB_ENV"
          ls -lh dist/
          unzip -l "dist/${BASE}.apk" | sort -k1 -n -r | head -n 15

      - name: Upload Release APK Artifact
        uses: actions/upload-artifact@v4
        with:
          name: ${{ env.APK_BASE }}
          path: dist/${{ env.APK_BASE }}.apk

      - name: Publish GitHub Release (tags only)
        if: startsWith(github.ref, 'refs/tags/v')
        uses: softprops/action-gh-release@v2
        with:
          name: OmniBrowser VPN Tunnel Pro ${{ github.ref_name }}
          body_path: RELEASE_NOTES.md
          files: dist/${{ env.APK_BASE }}.apk
          prerelease: ${{ contains(github.ref_name, '-') }}
          make_latest: ${{ !contains(github.ref_name, '-') }}

